import { GATES } from '@qforge/language';
import { Opcode, displayAngle, type IrInstruction, type IrModule } from '@qforge/compiler';
import {
  singleQubitMatrix,
  type Complex,
  type Matrix2,
  type Statevector,
} from '@qforge/simulator';

/**
 * Structured, computed facts about one step of execution.
 *
 * Everything here is *derived from the simulator's own numbers*. Nothing is a
 * stored sentence about what a gate "usually" does, and nothing is generated by
 * a language model. That rule exists because a plausible-sounding but wrong
 * explanation of a quantum circuit is worse than none: a learner has no way to
 * tell the difference, and the whole point of this tool is that they can check.
 *
 * Where a claim cannot be computed, it is not made.
 */

export interface AmplitudeChange {
  readonly index: number;
  readonly label: string;
  readonly before: Complex;
  readonly after: Complex;
  readonly probabilityBefore: number;
  readonly probabilityAfter: number;
}

export interface QubitEntanglement {
  readonly qubit: number;
  readonly label: string;
  /** Length of the Bloch vector: 1 is pure, 0 is maximally mixed. */
  readonly purityLength: number;
  readonly entangled: boolean;
}

export type StepFact =
  | { readonly kind: 'deterministic'; readonly text: string }
  | { readonly kind: 'probability'; readonly text: string }
  | { readonly kind: 'structure'; readonly text: string }
  | { readonly kind: 'measurement'; readonly text: string };

export interface StepExplanation {
  readonly headline: string;
  /** The gate's own description from the language's gate table. */
  readonly description?: string;
  /** 2x2 matrix, for single-qubit gates only. */
  readonly matrix?: Matrix2;
  readonly matrixCaption?: string;
  readonly operands: ReadonlyArray<{ readonly role: string; readonly label: string }>;
  readonly changes: readonly AmplitudeChange[];
  readonly entanglement: readonly QubitEntanglement[];
  /** Computed observations, each one checkable against the numbers shown. */
  readonly facts: readonly StepFact[];
}

const ROLES: Partial<Record<Opcode, readonly string[]>> = {
  [Opcode.Cx]: ['control', 'target'],
  [Opcode.Ccx]: ['control', 'control', 'target'],
  [Opcode.Cz]: ['qubit', 'qubit'],
  [Opcode.Swap]: ['qubit', 'qubit'],
};

const NEGLIGIBLE = 1e-12;

function probability(amplitude: Complex): number {
  return amplitude.re * amplitude.re + amplitude.im * amplitude.im;
}

function approxEqual(a: number, b: number, tolerance = 1e-9): boolean {
  return Math.abs(a - b) <= tolerance;
}

/**
 * Describe what one instruction did, from the states either side of it.
 *
 * `before` and `after` are the recorded states; when the trace dropped
 * amplitudes for memory reasons the caller passes undefined, and the
 * explanation degrades to what can still be computed rather than guessing.
 */
export function explainStep(
  instruction: IrInstruction,
  module: IrModule,
  before: Statevector | undefined,
  after: Statevector | undefined,
  measurement?: { outcome: 0 | 1; p0: number; p1: number },
  conditionHeld?: boolean,
): StepExplanation {
  const signature = GATES.get(instruction.opcode);
  const roles = ROLES[instruction.opcode];
  const label = (q: number) => module.qubitLabels[q] ?? `q${q}`;

  const operands = instruction.qubits.map((q, i) => ({
    role: roles?.[i] ?? 'qubit',
    label: label(q),
  }));

  const params = instruction.params.length
    ? `(${instruction.params.map((p) => displayAngle(p)).join(', ')})`
    : '';

  const facts: StepFact[] = [];

  // --- what the predicate did, if there was one ---
  if (instruction.condition) {
    facts.push({
      kind: 'structure',
      text:
        conditionHeld === false
          ? `The condition ${instruction.condition.text} did not hold on this run, so nothing was applied.`
          : `The condition ${instruction.condition.text} held, so the operation was applied.`,
    });
  }

  // --- amplitude changes, computed ---
  const changes: AmplitudeChange[] = [];
  if (before && after) {
    for (let i = 0; i < after.size; i++) {
      const b = before.amplitude(i);
      const a = after.amplitude(i);
      if (Math.abs(a.re - b.re) <= NEGLIGIBLE && Math.abs(a.im - b.im) <= NEGLIGIBLE) continue;
      changes.push({
        index: i,
        label: after.basisLabel(i),
        before: b,
        after: a,
        probabilityBefore: probability(b),
        probabilityAfter: probability(a),
      });
    }
  }

  // --- entanglement, computed from reduced density matrices ---
  const entanglement: QubitEntanglement[] = [];
  if (after && after.qubitCount > 1) {
    for (let q = 0; q < after.qubitCount; q++) {
      const bloch = after.blochVector(q);
      entanglement.push({
        qubit: q,
        label: label(q),
        purityLength: bloch.length,
        entangled: bloch.length < 1 - 1e-9,
      });
    }
  }

  // --- observations that follow from the numbers above ---
  if (before && after) {
    const probabilitiesUnchanged = changes.every((c) =>
      approxEqual(c.probabilityBefore, c.probabilityAfter),
    );
    if (changes.length > 0 && probabilitiesUnchanged) {
      facts.push({
        kind: 'probability',
        text:
          'Every amplitude that changed kept the same probability, so this step altered ' +
          'phase only. Measuring now would give exactly the same statistics as before it.',
      });
    }

    const createdSupport = changes.filter(
      (c) => c.probabilityBefore <= NEGLIGIBLE && c.probabilityAfter > NEGLIGIBLE,
    );
    const removedSupport = changes.filter(
      (c) => c.probabilityBefore > NEGLIGIBLE && c.probabilityAfter <= NEGLIGIBLE,
    );
    if (createdSupport.length > 0) {
      facts.push({
        kind: 'structure',
        text: `${createdSupport.length} basis state${createdSupport.length === 1 ? '' : 's'} that had zero amplitude now ${createdSupport.length === 1 ? 'has' : 'have'} some: ${createdSupport.map((c) => c.label).join(', ')}.`,
      });
    }
    if (removedSupport.length > 0) {
      facts.push({
        kind: 'structure',
        text: `${removedSupport.length} basis state${removedSupport.length === 1 ? '' : 's'} ${removedSupport.length === 1 ? 'was' : 'were'} cancelled to zero: ${removedSupport.map((c) => c.label).join(', ')}. That is interference.`,
      });
    }

    const nonZeroAfter = Array.from({ length: after.size }, (_, i) => i).filter(
      (i) => probability(after.amplitude(i)) > NEGLIGIBLE,
    );
    if (nonZeroAfter.length === 1) {
      facts.push({
        kind: 'deterministic',
        text: `The state is now exactly ${after.basisLabel(nonZeroAfter[0]!)}, so measuring every qubit would give that result with certainty.`,
      });
    }
  }

  if (measurement) {
    facts.push({
      kind: 'measurement',
      text:
        `Before this measurement the outcomes were P(0) = ${(measurement.p0 * 100).toFixed(2)}% ` +
        `and P(1) = ${(measurement.p1 * 100).toFixed(2)}%. Those are properties of the state. ` +
        `This run sampled ${measurement.outcome}; another seed may sample the other branch.`,
    });
    if (approxEqual(measurement.p0, 1) || approxEqual(measurement.p1, 1)) {
      facts.push({
        kind: 'deterministic',
        text: 'One outcome had probability 1, so this measurement was not random at all.',
      });
    }
  }

  const entangledQubits = entanglement.filter((e) => e.entangled);
  if (entangledQubits.length > 0) {
    const maximallyMixed = entangledQubits.filter((e) => e.purityLength < 1e-9);
    facts.push({
      kind: 'structure',
      text:
        maximallyMixed.length > 0
          ? `${maximallyMixed.map((e) => e.label).join(' and ')} ${maximallyMixed.length === 1 ? 'has' : 'have'} a Bloch vector of length 0: maximally mixed. ${maximallyMixed.length === 1 ? 'It has' : 'They have'} no state of ${maximallyMixed.length === 1 ? 'its' : 'their'} own, only correlations with the rest.`
          : `${entangledQubits.map((e) => e.label).join(', ')} ${entangledQubits.length === 1 ? 'is' : 'are'} entangled with the rest of the register, so no single-qubit description applies.`,
    });
  }

  const matrix =
    instruction.qubits.length === 1 && instruction.opcode !== Opcode.Measure
      ? singleQubitMatrix(instruction.opcode, instruction.params)
      : undefined;

  return {
    headline:
      instruction.opcode === Opcode.Measure
        ? `measure ${label(instruction.qubits[0]!)}`
        : `${instruction.opcode}${params} on ${instruction.qubits.map(label).join(', ')}`,
    ...(signature ? { description: signature.description } : {}),
    ...(matrix
      ? {
          matrix,
          matrixCaption:
            instruction.params.length > 0
              ? `Evaluated at ${instruction.params.map((p) => displayAngle(p)).join(', ')}.`
              : undefined,
        }
      : {}),
    operands,
    changes,
    entanglement,
    facts,
  };
}
